def main():
    argv = sys.argv
    if len(argv) < 2:
        fail(2)
    if argv[1] == "route":
        if len(argv) != 4:
            fail(2)
        file_path, source = argv[2], argv[3]
        nodes, links, node_set = load_network(file_path)
        if source not in node_set:
            fail(5)
        result = compute_routes(nodes, links, source)
    elif argv[1] == "rolepath":
        if len(argv) != 6:
            fail(2)
        file_path, source, destination, limit_text = (
            argv[2], argv[3], argv[4], argv[5])
        names, links, kind_of = load_role_network(file_path)
        if source not in kind_of or destination not in kind_of:
            fail(5)
        if kind_of[source] == "pseudo" or kind_of[destination] == "pseudo":
            fail(5)
        if (not limit_text
                or any(c not in "0123456789" for c in limit_text)):
            fail(5)
        limit_digits = limit_text.lstrip("0") or "0"
        if len(limit_digits) > 10:
            fail(5)
        limit = int(limit_digits)
        if limit > MAX_COST:
            fail(5)
        result = compute_rolepath(names, links, kind_of, source,
                                  destination, limit)
    elif argv[1] == "roletable":
        if len(argv) != 4:
            fail(2)
        file_path, source = argv[2], argv[3]
        names, links, kind_of = load_role_network(file_path)
        if source not in kind_of or kind_of[source] == "pseudo":
            fail(5)
        result = compute_roletable(names, links, kind_of, source)
    elif argv[1] == "ecmp":
        if len(argv) != 5:
            fail(2)
        file_path, source, flow = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path)
        if not 1 <= len(flow) <= MAX_FLOW_LEN:
            fail(5)
        try:
            flow.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_ecmp(nodes, links, source, flow)
    elif argv[1] == "metric":
        if len(argv) != 5:
            fail(2)
        file_path, source, order = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path, metrics=True)
        order_names = order.split(",")
        if (len(order_names) != 4
                or set(order_names) != {"hop", "cost", "bandwidth", "latency"}
                or len(set(order_names)) != 4):
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_metric(nodes, links, source, order_names)
    elif argv[1] == "wm":
        if len(argv) != 5:
            fail(2)
        file_path, source, weights_text = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path, metrics=True,
                                              strict=True)
        try:
            weights = json.loads(weights_text,
                                 parse_constant=_reject_constant,
                                 parse_float=_finite_float,
                                 object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if (not isinstance(weights, list) or len(weights) != 4
                or any(type(w) is not int or not 0 <= w <= MAX_COST
                       for w in weights)
                or all(w == 0 for w in weights)):
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_wm(nodes, links, source, weights)
    elif argv[1] == "wmecmp":
        if len(argv) != 6:
            fail(2)
        file_path, source, flow = argv[2], argv[3], argv[4]
        weights_text = argv[5]
        nodes, links, node_set = load_network(file_path, metrics=True,
                                              strict=True)
        try:
            weights = json.loads(weights_text,
                                 parse_constant=_reject_constant,
                                 parse_float=_finite_float,
                                 object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if (not isinstance(weights, list) or len(weights) != 4
                or any(type(w) is not int or not 0 <= w <= MAX_COST
                       for w in weights)
                or all(w == 0 for w in weights)):
            fail(5)
        if not 1 <= len(flow) <= MAX_FLOW_LEN:
            fail(5)
        try:
            flow.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_wmecmp(nodes, links, source, flow, weights)
    elif argv[1] == "wmconverge":
        if len(argv) != 9:
            fail(2)

